'use client';
import type { ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Avatar, enter } from '../lib/motion';
import '../designme.css';
import './agenda.css';

export interface AgendaPerson {
  /** Like "MK" */
  initials: string;
  /** The avatar's colour, like 'var(--dm-av-l)' */
  color: string;
}

export interface AgendaItem {
  /** Identifies the item for `open`. Defaults to its title */
  key?: string;
  /** Like "11:30" */
  time: string;
  /** Like "Agent demo" */
  title: string;
  /** The quiet line under the title, like "30 min, Zoom" */
  detail?: string;
  people?: AgendaPerson[];
  /** Already over: the item fades back, and the now line sits after the last one */
  past?: boolean;
  /** What the agent prepared, shown when the item opens. Items without notes don't open */
  notes?: ReactNode[];
  /** A button at the end of the notes, like "Join in 48 min" */
  action?: { label: string; onClick?: () => void };
}

export interface AgendaProps {
  items: AgendaItem[];
  /** Like "Today" */
  title?: string;
  /** Under the title, like "Monday, Oct 19" */
  subtitle?: string;
  /** The tag in the corner. Defaults to "4 events" */
  count?: string;
  /** The time on the now line, like "10:42". Leave it out for no line */
  now?: string;
  /** The item whose notes are open, by key. Leave it out to let each item toggle */
  open?: string | null;
  defaultOpen?: string | null;
  onOpenChange?: (key: string | null) => void;
  className?: string;
}

const keyOf = (item: AgendaItem) => item.key ?? item.title;

/** Today's events in order, with a line for now. Open one to see what the agent prepared for it. */
export function Agenda({ items, title = 'Today', subtitle, count, now, open, defaultOpen = null, onOpenChange, className }: AgendaProps) {
  const [opened, setOpened] = useControllable(open, defaultOpen, onOpenChange);
  // the now line goes after the last item that is over
  const lastPast = items.reduce((at, item, i) => item.past ? i : at, -1);
  // rows and the now line stagger in together, in the order they sit
  let n = 0;
  const row = (item: AgendaItem) => {
    const k = keyOf(item), isOpen = opened === k && !!item.notes?.length;
    const notes = item.notes ?? [];
    return (
      <button key={k} type="button" className={cx('dm-agx-e', item.past && 'dm-past', isOpen && 'dm-open', enter().className)} style={enter(n++ * 60).style}
        aria-expanded={notes.length ? isOpen : undefined} onClick={() => setOpened(isOpen || !notes.length ? null : k)}>
        <span className="dm-tm dm-num">{item.time}</span>
        <span className="dm-bar" />
        <span className="dm-t">
          <b>{item.title}</b>
          {item.detail && <span>{item.detail}</span>}
          {item.people?.length ? <span className="dm-who">{item.people.map((p, j) => <Avatar key={j} initials={p.initials} color={p.color} />)}</span> : null}
        </span>
        {isOpen && (
          <div className="dm-agx-prep">
            {notes.map((t, j) => <div key={j} {...enter(j * 60)}><Icon name="spark" size="xs" /><span>{t}</span></div>)}
            {item.action && <span className="dm-pill dm-accent dm-sm dm-agx-join dm-enter" style={enter(notes.length * 60).style}
              onClick={e => { if (item.action?.onClick) { e.stopPropagation(); item.action.onClick(); } }}>{item.action.label}</span>}
          </div>
        )}
      </button>
    );
  };

  return (
    <div data-dm="" className={cx('dm-agx dm-panel', className)}>
      <div className="dm-agx-h">
        <div><b>{title}</b>{subtitle && <span className="dm-muted">{subtitle}</span>}</div>
        <span className="dm-tag dm-b">{count ?? `${items.length} ${items.length === 1 ? 'event' : 'events'}`}</span>
      </div>
      <div className="dm-agx-list">
        {items.flatMap((item, i) => {
          const out = [row(item)];
          if (now && i === lastPast) out.push(<div key="now" className="dm-agx-now dm-enter" style={enter(n++ * 60).style}><i />{now}</div>);
          return out;
        })}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Agenda ---------- */
.dm-agx{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-agx-h{display:flex;align-items:center;justify-content:space-between;padding:2px var(--dm-s-1)}
.dm-agx-h>div{display:flex;flex-direction:column;font-size:13.5px}
.dm-agx-h b{font-weight:500}
.dm-agx-h .dm-muted{font-size:12px}
.dm-agx-list{display:flex;flex-direction:column;gap:var(--dm-s-1);position:relative}
.dm-agx-e{display:grid;grid-template-columns:52px 3px 1fr;gap:10px;padding:var(--dm-s-2) 6px;border-radius:calc(10px * var(--dm-rk));text-align:left;width:100%;transition:background .2s,opacity .3s}
@media (hover:hover) and (pointer:fine){.dm-agx-e:hover{background:var(--dm-row)}}
/* the open event needs no fill of its own: it sits on the panel's white and its prep notes show it is open */
.dm-agx-e.dm-open{background:var(--dm-surface)}
@media (hover:hover) and (pointer:fine){.dm-agx-e.dm-open:hover{background:var(--dm-surface)}}
/* a past event: its title steps down to muted and its bar fades, the text stays readable */
.dm-agx-e.dm-past .dm-t b{color:var(--dm-muted)}.dm-agx-e.dm-past .dm-bar{opacity:.5}
.dm-agx-e .dm-tm{font-size:12px;color:var(--dm-muted);padding-top:1px}
.dm-agx-e .dm-bar{border-radius:2px;background:var(--dm-accent-mark,var(--dm-accent))}
.dm-agx-e .dm-t{display:flex;flex-direction:column;font-size:13px;min-width:0}
.dm-agx-e .dm-t b{font-weight:500}
.dm-agx-e .dm-t span{font-size:12px;color:var(--dm-muted)}
.dm-agx-e .dm-who{display:flex;margin-top:6px}
.dm-agx-e .dm-who .dm-av{width:20px;height:20px;font-size:8.5px;color:#fff;margin-right:-2px;box-shadow:0 0 0 1.5px var(--dm-surface)}
.dm-agx-prep{grid-column:3;font-size:12.5px;line-height:1.5;color:var(--dm-fg2);display:flex;flex-direction:column;gap:5px;padding-top:var(--dm-s-2)}
.dm-agx-prep div{display:flex;gap:7px;align-items:flex-start}
.dm-agx-prep svg{color:var(--dm-accent-fg,var(--dm-accent));margin-top:3px;flex:none}
.dm-agx-now{display:flex;align-items:center;gap:6px;margin:2px 0;font-size:11px;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;padding-left:6px}
.dm-agx-now::after{content:"";flex:1;height:2px;background:var(--dm-accent-mark,var(--dm-accent));border-radius:1px}
.dm-agx-now i{width:7px;height:7px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent));animation:dm-agnow 2s ease-in-out infinite}
@keyframes dm-agnow{50%{box-shadow:0 0 0 5px var(--dm-accent-bg)}}
.dm-agx-join{margin-top:var(--dm-s-2);align-self:flex-start}
